python3 -c "
import json,collections
ps=json.load(open('/opt/trading-bot/positions_regr/positions.json'))
om={o['id']:o for o in json.load(open('/opt/trading-bot/positions_regr/orders.json'))}
rows=[]
for p in ps:
    if p['status']!='closed' or p.get('src')!='chan': continue
    o=om.get(p.get('order_id')) or {}
    rows.append(dict(id=p['id'],setup=o.get('setup'),cnt=bool(o.get('counter')),side=p['side'],ct=(o.get('chan') or {}).get('type'),reg=(o.get('regime') or {}).get('regime'),net=p.get('net_pct') or 0,r=p.get('r_mult') or 0,mfeR=(p.get('mfe_pct') or 0)/p['R_pct'],rule=p.get('rule')))
print('closed chan positions',len(rows),'ids',rows[0]['id'],'-',rows[-1]['id'])
def agg(keyf,sel=lambda r:True,title=''):
    g=collections.defaultdict(list)
    for r in rows:
        if sel(r): g[keyf(r)].append(r)
    print('==',title)
    for k,v in sorted(g.items(),key=lambda kv:str(kv[0])):
        n=len(v);w=sum(1 for x in v if x['net']>0)
        print('  %-34s n=%2d win=%2d net_sum=%6.2f avg_mfeR=%.2f ids=%s'%(k,n,w,sum(x['net'] for x in v),sum(x['mfeR'] for x in v)/n,[x['id'] for x in v][-12:]))
agg(lambda r:(r['setup'],'counter' if r['cnt'] else 'main'),title='by setup x counter(all)')
agg(lambda r:(r['setup'],'counter' if r['cnt'] else 'main',r['reg']),sel=lambda r:r['id']>=224,title='since #224 by setup x counter x regime')
agg(lambda r:(r['setup'],r['side'],r['ct']),sel=lambda r:r['setup']=='breakout',title='breakout by side x chan type')
